    <el-dialog v-model="previewOpen" title="公开人物视图预览（非公开草稿接口）" width="min(750px, 96vw)"><div v-if="preview"><h3>{{ preview.name }}</h3><p>{{ preview.sourceType }} · {{ preview.demo ? '演示' : '人工维护' }} · {{ labels[preview.status] }} · {{ preview.publiclyVisible ? '已公开' : '当前不可公开读取' }}</p><p>{{ preview.traderId }} · {{ preview.statisticPeriodId }}</p><p>{{ preview.bio }}</p><p>{{ preview.disclosure }}</p><p>人工 ROI {{ preview.manualRoi ?? '—' }}；人工胜率 {{ preview.manualWinRate ?? '—' }}；人工回撤 {{ preview.manualMaxDrawdown ?? '—' }}。未提供数字不造数。</p><p>{{ preview.metricBasisNote }}</p><p>{{ preview.sourceNote }}</p><p>{{ preview.curveDisclosure }}</p><p>{{ preview.historyDisclosure }}</p><p>{{ preview.riskNote }}</p></div></el-dialog>
    <el-dialog v-model="auditOpen" title="交易员展示修改前后审计" width="min(950px, 96vw)"><details v-for="a in audits" :key="a.id"><summary>{{ a.capturedAt }} · {{ a.actor }} · {{ a.action }} · {{ a.reason }}</summary><p>人物 {{ a.traderId }} · 子记录 {{ a.objectId || '资料 / 批量' }}</p><h4>修改前</h4><pre>{{ a.beforeJson || '新增记录' }}</pre><h4>修改后</h4><pre>{{ a.afterJson || '已删除' }}</pre></details><p v-if="!audits.length">暂无修改审计</p><div class="actions"><el-button v-permission="'traders:view'" :disabled="auditPage === 0" @click="auditPage--; showAudit()">上一页审计</el-button><span>第 {{ auditPage + 1 }} 页</span><el-button v-permission="'traders:view'" :disabled="audits.length < 50" @click="auditPage++; showAudit()">下一页审计</el-button></div></el-dialog>
